// Package clock holds the basic time types: durations in whole minutes and calendar dates.
package clock

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

// ErrInvalidDuration is wrapped by every error returned from ParseDuration.
var ErrInvalidDuration = errors.New("invalid duration")

// ErrInvalidDate is wrapped by every error returned from ParseDate.
var ErrInvalidDate = errors.New("invalid date")

// Minutes is a length of time in whole minutes.
type Minutes int

// digits reports whether s is non-empty and only ASCII digits.
func digits(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return s != ""
}

// ParseDuration parses H:MM or HH:MM into minutes. (T1)
func ParseDuration(s string) (Minutes, error) {
	hours, minutes, ok := strings.Cut(s, ":")
	if !ok || len(hours) > 2 || len(minutes) != 2 || !digits(hours) || !digits(minutes) ||
		minutes > "59" {
		return 0, fmt.Errorf("%w: %q", ErrInvalidDuration, s)
	}
	h, _ := strconv.Atoi(hours)
	m, _ := strconv.Atoi(minutes)
	return Minutes(h*60 + m), nil
}

// String formats m as hours, a colon and two-digit minutes. (T1)
func (m Minutes) String() string {
	sign, v := "", uint64(m)
	if m < 0 {
		sign, v = "-", -v
	}
	return fmt.Sprintf("%s%d:%02d", sign, v/60, v%60)
}

// ParseDate parses YYYY-MM-DD into midnight UTC on that date. (T2)
func ParseDate(s string) (time.Time, error) {
	bad := fmt.Errorf("%w: %q", ErrInvalidDate, s)
	if len(s) != 10 || s[4] != '-' || s[7] != '-' || !digits(s[:4]) || !digits(s[5:7]) ||
		!digits(s[8:]) {
		return time.Time{}, bad
	}
	year, _ := strconv.Atoi(s[:4])
	month, _ := strconv.Atoi(s[5:7])
	day, _ := strconv.Atoi(s[8:])
	t := time.Date(year, time.Month(month), day, 0, 0, 0, 0, time.UTC)
	if year < 1 || t.Year() != year || int(t.Month()) != month || t.Day() != day {
		return time.Time{}, bad
	}
	return t, nil
}

// WeekStart returns midnight UTC on the last Monday strictly before t's date in UTC. (T2, as
// corrected)
func WeekStart(t time.Time) time.Time {
	year, month, day := t.UTC().Date()
	date := time.Date(year, month, day, 0, 0, 0, 0, time.UTC)
	back := (int(date.Weekday()) + 6) % 7
	if back == 0 {
		back = 7
	}
	return date.AddDate(0, 0, -back)
}

