// Package money holds amounts of money in whole cents.
package money

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// ErrInvalidAmount is wrapped by every error returned from ParseAmount.
var ErrInvalidAmount = errors.New("invalid amount")

// Cents is an amount of money in cents.
type Cents int64

// digits reports whether s is non-empty and only ASCII digits.
func digits(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return s != ""
}

// ParseAmount parses an amount such as 25 or 25.50 into cents. (T3)
func ParseAmount(s string) (Cents, error) {
	whole, cents, dot := strings.Cut(s, ".")
	if len(whole) > 9 || !digits(whole) || (dot && (len(cents) != 2 || !digits(cents))) {
		return 0, fmt.Errorf("%w: %q", ErrInvalidAmount, s)
	}
	units, _ := strconv.ParseInt(whole, 10, 64)
	var hundredths int64
	if dot {
		hundredths, _ = strconv.ParseInt(cents, 10, 64)
	}
	return Cents(units*100 + hundredths), nil
}

// String formats c with comma-grouped dollars and two decimal places. (T3)
func (c Cents) String() string {
	sign, v := "", uint64(c)
	if c < 0 {
		sign, v = "-", -v
	}
	whole := strconv.FormatUint(v/100, 10)
	var grouped strings.Builder
	for i, digit := range whole {
		if i > 0 && (len(whole)-i)%3 == 0 {
			grouped.WriteByte(',')
		}
		grouped.WriteRune(digit)
	}
	return fmt.Sprintf("%s%s.%02d", sign, grouped.String(), v%100)
}

