// Package entry parses timesheet lines and files.
package entry

import (
	"errors"
	"fmt"
	"io"
	"strings"
	"time"

	"example.com/timesheet/clock"
)

// ErrInvalidEntry is wrapped by every error for a malformed timesheet line.
var ErrInvalidEntry = errors.New("invalid entry")

// ErrDuplicateEntry is wrapped by the error for a repeated employee and date.
var ErrDuplicateEntry = errors.New("duplicate entry")

// Entry is one employee's time worked on one date.
type Entry struct {
	Date     time.Time
	Employee string
	Worked   clock.Minutes
}

// ValidEmployee reports whether id is a valid employee ID. (T4)
func ValidEmployee(id string) bool {
	if len(id) < 1 || len(id) > 32 || id[0] < 'a' || id[0] > 'z' {
		return false
	}
	for i := 0; i < len(id); i++ {
		c := id[i]
		if (c < 'a' || c > 'z') && (c < '0' || c > '9') && c != '-' {
			return false
		}
	}
	return true
}

// ParseEntry parses one timesheet line: date,employee,time. (T4)
func ParseEntry(line string) (Entry, error) {
	fields := strings.Split(line, ",")
	if len(fields) != 3 {
		return Entry{}, fmt.Errorf("%w: %d fields, want 3", ErrInvalidEntry, len(fields))
	}
	for i := range fields {
		fields[i] = strings.Trim(fields[i], " \t")
	}
	date, err := clock.ParseDate(fields[0])
	if err != nil {
		return Entry{}, fmt.Errorf("%w: date: %w", ErrInvalidEntry, err)
	}
	if !ValidEmployee(fields[1]) {
		return Entry{}, fmt.Errorf("%w: employee %q", ErrInvalidEntry, fields[1])
	}
	worked, err := clock.ParseDuration(fields[2])
	if err != nil {
		return Entry{}, fmt.Errorf("%w: time: %w", ErrInvalidEntry, err)
	}
	if worked <= 0 || worked > 24*60 {
		return Entry{}, fmt.Errorf("%w: time %s is not above 0:00 and at most 24:00", ErrInvalidEntry, worked)
	}
	return Entry{Date: date, Employee: fields[1], Worked: worked}, nil
}

// ParseEntries parses a whole timesheet file. (T5)
func ParseEntries(r io.Reader) ([]Entry, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("reading the timesheet: %w", err)
	}
	entries := []Entry{}
	seen := map[string]bool{}
	for i, line := range strings.Split(strings.TrimSuffix(string(data), "\n"), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if rest := strings.TrimLeft(line, " \t"); rest == "" || rest[0] == '#' {
			continue
		}
		e, err := ParseEntry(line)
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", i+1, err)
		}
		key := e.Employee + " " + e.Date.Format("2006-01-02")
		if seen[key] {
			return nil, fmt.Errorf("line %d: %w for %s on %s", i+1, ErrDuplicateEntry, e.Employee,
				e.Date.Format("2006-01-02"))
		}
		seen[key] = true
		entries = append(entries, e)
	}
	return entries, nil
}

