// Package payroll applies the overtime and pay rules and reads hourly rates.
package payroll

import (
	"errors"
	"fmt"
	"io"
	"sort"
	"strings"
	"time"

	"example.com/timesheet/clock"
	"example.com/timesheet/entry"
	"example.com/timesheet/money"
)

// ErrInvalidRate is wrapped by every error for a bad line in a rate file.
var ErrInvalidRate = errors.New("invalid rate")

// WeekSummary is one employee's regular and overtime minutes in one week.
type WeekSummary struct {
	Employee  string
	WeekStart time.Time
	Regular   clock.Minutes
	Overtime  clock.Minutes
}

// Summarize totals entries per employee per week and splits off overtime. (T6)
func Summarize(entries []entry.Entry) []WeekSummary {
	type key struct {
		employee string
		week     time.Time
	}
	totals := map[key]clock.Minutes{}
	for _, e := range entries {
		// WeekStart gives the last Monday strictly before a date, so the next day's is the
		// Monday on or before the entry's date.
		week := clock.WeekStart(e.Date.UTC().AddDate(0, 0, 1))
		totals[key{e.Employee, week}] += e.Worked
	}
	out := make([]WeekSummary, 0, len(totals))
	for k, total := range totals {
		regular := min(total, 40*60)
		out = append(out, WeekSummary{Employee: k.employee, WeekStart: k.week, Regular: regular,
			Overtime: total - regular})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Employee != out[j].Employee {
			return out[i].Employee < out[j].Employee
		}
		return out[i].WeekStart.Before(out[j].WeekStart)
	})
	return out
}

// WeekPay returns the pay for one week at an hourly rate. (T7)
func WeekPay(rate money.Cents, s WeekSummary) money.Cents {
	if rate < 0 || s.Regular < 0 || s.Overtime < 0 {
		return 0
	}
	// rate × (2 × Regular + 3 × Overtime) / 120, rounded half up.
	scaled := int64(rate) * (2*int64(s.Regular) + 3*int64(s.Overtime))
	return money.Cents((scaled + 60) / 120)
}

// ParseRates parses a rate file of employee=amount lines. (T8)
func ParseRates(r io.Reader) (map[string]money.Cents, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, fmt.Errorf("reading the rates: %w", err)
	}
	rates := map[string]money.Cents{}
	for i, line := range strings.Split(strings.TrimSuffix(string(data), "\n"), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if rest := strings.TrimLeft(line, " \t"); rest == "" || rest[0] == '#' {
			continue
		}
		bad := func(why string) error { return fmt.Errorf("line %d: %w: %s", i+1, ErrInvalidRate, why) }
		id, amount, ok := strings.Cut(line, "=")
		if !ok {
			return nil, bad("missing =")
		}
		id, amount = strings.Trim(id, " \t"), strings.Trim(amount, " \t")
		// The amount first: a malformed one is ErrInvalidAmount whatever else is wrong.
		rate, err := money.ParseAmount(amount)
		if err != nil {
			return nil, fmt.Errorf("line %d: %w: %w", i+1, ErrInvalidRate, err)
		}
		if !entry.ValidEmployee(id) {
			return nil, bad(fmt.Sprintf("employee %q", id))
		}
		if rate <= 0 {
			return nil, bad("the rate must be greater than 0")
		}
		if _, repeated := rates[id]; repeated {
			return nil, bad("repeated employee " + id)
		}
		rates[id] = rate
	}
	return rates, nil
}

