// Package report produces the weekly payroll report.
package report

import (
	"errors"
	"fmt"
	"io"
	"strings"

	"example.com/timesheet/clock"
	"example.com/timesheet/entry"
	"example.com/timesheet/money"
	"example.com/timesheet/payroll"
)

// ErrMissingRate is wrapped by the error for an employee with entries but no rate.
var ErrMissingRate = errors.New("missing rate")

// Weekly builds the weekly payroll report from a timesheet and a rate file. (T9)
func Weekly(entries io.Reader, rates io.Reader) (string, error) {
	list, err := entry.ParseEntries(entries)
	if err != nil {
		return "", fmt.Errorf("entries: %w", err)
	}
	rateOf, err := payroll.ParseRates(rates)
	if err != nil {
		return "", fmt.Errorf("rates: %w", err)
	}
	weeks := payroll.Summarize(list)
	width := 8
	for _, w := range weeks {
		if _, ok := rateOf[w.Employee]; !ok {
			return "", fmt.Errorf("%w for %s", ErrMissingRate, w.Employee)
		}
		width = max(width, len(w.Employee))
	}
	var b strings.Builder
	line := func(week, employee, regular, overtime, pay string) {
		fmt.Fprintf(&b, "%-10s  %-*s  %7s  %8s  %12s\n", week, width, employee, regular, overtime, pay)
	}
	line("WEEK", "EMPLOYEE", "REGULAR", "OVERTIME", "PAY")
	var regular, overtime clock.Minutes
	var total money.Cents
	for _, w := range weeks {
		pay := payroll.WeekPay(rateOf[w.Employee], w)
		line(w.WeekStart.Format("2006-01-02"), w.Employee, w.Regular.String(), w.Overtime.String(),
			pay.String())
		regular, overtime, total = regular+w.Regular, overtime+w.Overtime, total+pay
	}
	line("TOTAL", "", regular.String(), overtime.String(), total.String())
	return b.String(), nil
}

