package timesheet_test

// The hidden oracle, one or more tests per requirement. T2's WeekStart cases follow the
// corrected meaning (the last Monday strictly before the date). The tests whose results depend
// on that meaning through a caller the dependency list names are listed in the protected file's
// `trap`: T6's in `cases`, for C2. No dependent belongs to T2's own developer, so `side_cases`
// is empty. Every other test is untagged, and no untagged T6 test has a Monday date.

import (
	"errors"
	"fmt"
	"math"
	"reflect"
	"strings"
	"testing"
	"testing/iotest"
	"time"

	"example.com/timesheet/clock"
	"example.com/timesheet/entry"
	"example.com/timesheet/money"
	"example.com/timesheet/payroll"
	"example.com/timesheet/report"
)

func date(t *testing.T, s string) time.Time {
	t.Helper()
	d, err := time.Parse("2006-01-02", s)
	if err != nil {
		t.Fatal(err)
	}
	return d
}

func show(t time.Time) string { return t.Format(time.RFC3339) + " " + t.Location().String() }

func TestClockParseDuration(t *testing.T) {
	for s, want := range map[string]clock.Minutes{"7:30": 450, "07:30": 450, "0:05": 5, "00:00": 0,
		"99:59": 5999, "1:00": 60, "24:00": 1440} {
		got, err := clock.ParseDuration(s)
		if got != want || err != nil {
			t.Errorf("ParseDuration(%q) = %d, %v; want %d, nil", s, got, err, want)
		}
	}
	for _, s := range []string{"", " 7:30", "7:30 ", "7 :30", "+7:30", "-7:30", "100:00", "7:3",
		"7:60", "7:99", "730", "7.30", ":30", "7:", "7:30:00", "٧:٣٠", "7:3a", "a:30", "7::30"} {
		got, err := clock.ParseDuration(s)
		if got != 0 || !errors.Is(err, clock.ErrInvalidDuration) {
			t.Errorf("ParseDuration(%q) = %d, %v; want 0, ErrInvalidDuration", s, got, err)
		}
	}
}

func TestClockMinutesString(t *testing.T) {
	for m, want := range map[clock.Minutes]string{0: "0:00", 5: "0:05", 59: "0:59", 60: "1:00",
		450: "7:30", 6000: "100:00", 5999: "99:59", -90: "-1:30", -5: "-0:05", -60: "-1:00"} {
		if got := m.String(); got != want {
			t.Errorf("Minutes(%d).String() = %q, want %q", int(m), got, want)
		}
	}
}

func TestClockParseDate(t *testing.T) {
	for _, s := range []string{"2028-02-29", "2026-11-09", "0001-01-01", "9999-12-31", "2000-02-29",
		"2026-12-31"} {
		got, err := clock.ParseDate(s)
		if err != nil || got.Format("2006-01-02") != s || got.Location() != time.UTC ||
			got.Hour()+got.Minute()+got.Second()+got.Nanosecond() != 0 {
			t.Errorf("ParseDate(%q) = %s, %v; want midnight UTC on that date", s, show(got), err)
		}
	}
	for _, s := range []string{"2026-02-29", "2026-13-01", "0000-01-01", "2026-1-05", "2026/01/05",
		" 2026-01-05", "2026-01-05 ", "2026-01-05\n", "", "1900-02-29", "2026-04-31", "2026-00-10",
		"2026-01-00", "+026-01-05", "20260-1-05", "2026-01-5x", "2026-01-05T00:00:00Z"} {
		got, err := clock.ParseDate(s)
		if !got.IsZero() || !errors.Is(err, clock.ErrInvalidDate) {
			t.Errorf("ParseDate(%q) = %s, %v; want the zero time, ErrInvalidDate", s, show(got), err)
		}
	}
}

// T2 as corrected: the last Monday strictly before the date.
func TestClockWeekStart(t *testing.T) {
	east := time.FixedZone("east", 10*3600)
	west := time.FixedZone("west", -8*3600)
	for _, c := range []struct {
		in   time.Time
		want string
	}{
		{date(t, "2026-11-08"), "2026-11-02"}, // Sunday
		{date(t, "2026-11-09"), "2026-11-02"}, // Monday
		{time.Date(2026, 11, 9, 23, 59, 0, 0, time.UTC), "2026-11-02"},
		{date(t, "2026-11-10"), "2026-11-09"}, // Tuesday
		{date(t, "2026-11-15"), "2026-11-09"}, // Sunday
		{date(t, "2027-01-01"), "2026-12-28"}, // Friday
		{date(t, "2027-01-04"), "2026-12-28"}, // Monday
		{date(t, "2024-03-04"), "2024-02-26"}, // Monday after a leap day
		// The calendar date in UTC counts: 2026-11-10 08:00 in east is 2026-11-09 22:00 UTC.
		{time.Date(2026, 11, 10, 8, 0, 0, 0, east), "2026-11-02"},
		// 2026-11-09 20:00 in west is 2026-11-10 04:00 UTC, a Tuesday.
		{time.Date(2026, 11, 9, 20, 0, 0, 0, west), "2026-11-09"},
	} {
		got := clock.WeekStart(c.in)
		want := date(t, c.want)
		if !got.Equal(want) || got.Location() != time.UTC || got.Format(time.RFC3339) != c.want+"T00:00:00Z" {
			t.Errorf("WeekStart(%s) = %s, want %s midnight UTC", c.in.Format(time.RFC3339), show(got), c.want)
		}
	}
}

