		if err != nil || !got.Date.Equal(want.Date) || got.Date.Location() != time.UTC ||
			got.Employee != want.Employee || got.Worked != want.Worked {
			t.Errorf("ParseEntry(%q) = %+v, %v; want %+v", line, got, err, want)
		}
	}
	for _, c := range []struct {
		line           string
		date, duration bool
	}{
		{"2026-11-02,alice", false, false},
		{"2026-11-02,alice,7:30,", false, false},
		{"2026-11-02,alice,7:30,x", false, false},
		{"", false, false},
		{"2026-02-29,alice,7:30", true, false},
		{"2026-11-2,alice,7:30", true, false},
		{",alice,7:30", true, false},
		{"2026-11-02,Alice,7:30", false, false},
		{"2026-11-02,,7:30", false, false},
		{"2026-11-02,alice,7:3", false, true},
		{"2026-11-02,alice,", false, true},
		{"2026-11-02,alice,100:00", false, true},
		{"2026-11-02,alice,0:00", false, false},
		{"2026-11-02,alice,24:01", false, false},
		{"2026-11-02,alice,99:59", false, false},
		// The first failing field: the date before the employee before the time.
		{"2026-02-30,Alice,7:3", true, false},
		{"2026-11-02,Alice,7:3", false, false},
	} {
		got, err := entry.ParseEntry(c.line)
