			errors.Is(err, clock.ErrInvalidDate) != c.date ||
			errors.Is(err, clock.ErrInvalidDuration) != c.duration {
			t.Errorf("ParseEntry(%q) = %+v, %v; want the zero Entry, ErrInvalidEntry, ErrInvalidDate %v, ErrInvalidDuration %v",
