func TestEntryParseEntries(t *testing.T) {
	file := "# timesheet\n\n2026-11-02,alice,7:30\r\n  \t\n  # bob next\n2026-11-02 , bob , 8:00\n2026-11-03,alice,1:15"
	got, err := entry.ParseEntries(strings.NewReader(file))
	want := []entry.Entry{{date(t, "2026-11-02"), "alice", 450}, {date(t, "2026-11-02"), "bob", 480},
		{date(t, "2026-11-03"), "alice", 75}}
	if err != nil || len(got) != len(want) {
		t.Fatalf("ParseEntries = %+v, %v; want %+v", got, err, want)
	}
	for i := range want {
		if !got[i].Date.Equal(want[i].Date) || got[i].Employee != want[i].Employee || got[i].Worked != want[i].Worked {
			t.Errorf("entry %d = %+v, want %+v", i, got[i], want[i])
		}
	}
	for _, file := range []string{"", "\n", "# only\n\n \t\r\n", "\r\n"} {
		got, err := entry.ParseEntries(strings.NewReader(file))
		if got == nil || len(got) != 0 || err != nil {
			t.Errorf("ParseEntries(%q) = %#v, %v; want an empty, non-nil slice", file, got, err)
		}
	}
	for _, c := range []struct {
		file, prefix   string
		date, duration bool
	}{
		{"2026-11-02,alice,7:30\n\n# c\n2026-11-02,alice", "line 4: ", false, false},
		{"2026-11-02,alice,7:30\n2026-13-02,bob,1:00\n", "line 2: ", true, false},
		{"\n\n2026-11-02,bob,1:60\n", "line 3: ", false, true},
		{"2026-11-02,bob,0:00", "line 1: ", false, false},
		{"2026-11-02,alice,7:30\n x2026-11-03,alice,1:00", "line 2: ", true, false},
		{"2026-11-02,alice,7:30\n2026-11-03,alice,7:30,\n", "line 2: ", false, false},
	} {
		got, err := entry.ParseEntries(strings.NewReader(c.file))
		if got != nil || err == nil || !strings.HasPrefix(err.Error(), c.prefix) ||
			!errors.Is(err, entry.ErrInvalidEntry) || errors.Is(err, entry.ErrDuplicateEntry) ||
			errors.Is(err, clock.ErrInvalidDate) != c.date ||
			errors.Is(err, clock.ErrInvalidDuration) != c.duration {
			t.Errorf("ParseEntries(%q) = %v, %v; want nil and a %q ErrInvalidEntry", c.file, got, err, c.prefix)
		}
	}
	dup := "2026-11-02,alice,7:30\n2026-11-02,bob,1:00\n# x\n 2026-11-02 , alice , 1:00\nbad\n"
	got, err = entry.ParseEntries(strings.NewReader(dup))
	if got != nil || err == nil || err.Error() != "line 4: duplicate entry for alice on 2026-11-02" ||
		!errors.Is(err, entry.ErrDuplicateEntry) || errors.Is(err, entry.ErrInvalidEntry) {
		t.Errorf("ParseEntries(duplicate) = %v, %v; want the line 4 duplicate error", got, err)
	}
	failure := errors.New("disk on fire")
	got, err = entry.ParseEntries(iotest.ErrReader(failure))
	if got != nil || !errors.Is(err, failure) {
		t.Errorf("ParseEntries(failing reader) = %v, %v; want nil and the read error", got, err)
	}
}

type week struct {
	employee, start   string
	regular, overtime clock.Minutes
}

func summaries(t *testing.T, got []payroll.WeekSummary) []week {
	t.Helper()
	out := []week{}
	for _, s := range got {
		if s.WeekStart.Location() != time.UTC || s.WeekStart.Hour()+s.WeekStart.Minute() != 0 {
			t.Errorf("%s's WeekStart %s is not midnight UTC", s.Employee, show(s.WeekStart))
		}
		out = append(out, week{s.Employee, s.WeekStart.Format("2006-01-02"), s.Regular, s.Overtime})
	}
	return out
}

// Weeks run Monday to Sunday, each identified by its Monday (C2-tagged: Monday dates and the
// Sunday-Monday boundary).
func TestSummarizeWeeks(t *testing.T) {
	east := time.FixedZone("east", 10*3600)
	entries := []entry.Entry{
		{date(t, "2026-11-08"), "alice", 60},  // Sunday
		{date(t, "2026-11-09"), "alice", 120}, // Monday
		{date(t, "2026-11-02"), "alice", 30},  // Monday
		{date(t, "2026-11-15"), "alice", 15},  // Sunday
		{date(t, "2026-11-16"), "bob", 2400},  // Monday
		{date(t, "2026-11-17"), "bob", 90},
		// 2026-11-10 07:00 in east is 2026-11-09 21:00 UTC, a Monday.
		{time.Date(2026, 11, 10, 7, 0, 0, 0, east), "carol", 45},
		{time.Date(2026, 11, 9, 23, 59, 0, 0, time.UTC), "carol", 5},
	}
	got := summaries(t, payroll.Summarize(entries))
	want := []week{{"alice", "2026-11-02", 90, 0}, {"alice", "2026-11-09", 135, 0},
		{"bob", "2026-11-16", 2400, 90}, {"carol", "2026-11-09", 50, 0}}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Summarize = %v, want %v", got, want)
	}
}

