func TestSummarizeOrder(t *testing.T) {
	for _, in := range [][]entry.Entry{nil, {}} {
		if got := payroll.Summarize(in); got == nil || len(got) != 0 {
			t.Errorf("Summarize(%#v) = %#v, want an empty, non-nil slice", in, got)
		}
	}
	entries := []entry.Entry{
		{date(t, "2026-11-18"), "bob", 60},
		{date(t, "2026-11-04"), "alice-2", 30},
		{date(t, "2026-11-11"), "alice", 20},
		{date(t, "2026-11-05"), "alice", 10},
		{date(t, "2026-11-04"), "bob", 40},
		{date(t, "2026-11-06"), "alice", 5},
	}
	before := append([]entry.Entry(nil), entries...)
	want := []week{{"alice", "2026-11-02", 15, 0}, {"alice", "2026-11-09", 20, 0},
		{"alice-2", "2026-11-02", 30, 0}, {"bob", "2026-11-02", 40, 0}, {"bob", "2026-11-16", 60, 0}}
	got := summaries(t, payroll.Summarize(entries))
	if !reflect.DeepEqual(got, want) {
		t.Errorf("Summarize = %v, want %v", got, want)
	}
	if !reflect.DeepEqual(entries, before) {
		t.Errorf("Summarize modified its input: %v", entries)
	}
	reversed := make([]entry.Entry, len(entries))
	for i, e := range entries {
		reversed[len(entries)-1-i] = e
	}
	if got := summaries(t, payroll.Summarize(reversed)); !reflect.DeepEqual(got, want) {
		t.Errorf("Summarize(reversed) = %v, want %v", got, want)
	}
}

