func TestWeeklyLayout(t *testing.T) {
	got, err := weekly("# none\n", "zed=1.00\n")
	want := "WEEK        EMPLOYEE  REGULAR  OVERTIME           PAY\n" +
		"TOTAL                    0:00      0:00          0.00\n"
	if got != want || err != nil {
		t.Errorf("Weekly(no entries) = %q, %v; want %q", got, err, want)
	}
	// A long ID widens EMPLOYEE; weeks sort by date; a long value pushes the line right.
	var file strings.Builder
	for d := 0; d < 7; d++ {
		fmt.Fprintf(&file, "2026-11-%02d,a-very-long-employee-id,24:00\n", 16+d)
	}
	file.WriteString("2026-11-11,a-very-long-employee-id,0:01\n2026-11-11,bo,1:00\n")
	got, err = weekly(file.String(), "bo=999999999.99\na-very-long-employee-id=0.01\nunused=3\n")
	want = "WEEK        EMPLOYEE                 REGULAR  OVERTIME           PAY\n" +
		"2026-11-09  a-very-long-employee-id     0:01      0:00          0.00\n" +
		"2026-11-16  a-very-long-employee-id    40:00    128:00          2.32\n" +
		"2026-11-09  bo                          1:00      0:00  999,999,999.99\n" +
		"TOTAL                                  41:01    128:00  1,000,000,002.31\n"
	if got != want || err != nil {
		t.Errorf("Weekly(long values) = %q, %v; want %q", got, err, want)
	}
	for _, line := range strings.Split(strings.TrimSuffix(got, "\n"), "\n") {
		if strings.HasSuffix(line, " ") {
			t.Errorf("trailing space in %q", line)
		}
	}
}

